## Mule HTTP Listener / APIKit → API Gateway + Lambda

The Mule `http:listener` or `apikit:router` element exposes an HTTP endpoint.
Replace with API Gateway (HTTP API or REST API) proxying to Lambda.

## Python — API Gateway Proxy Handler

```python
import json
import logging
import os

logger = logging.getLogger()
logger.setLevel(logging.INFO)

CORS_HEADERS = {
    "Access-Control-Allow-Origin": os.environ.get("CORS_ORIGIN", "*"),
    "Access-Control-Allow-Headers": "Content-Type,Authorization",
    "Access-Control-Allow-Methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS",
    "Content-Type": "application/json",
}


def handler(event, context):
    """
    API Gateway Lambda Proxy Integration.
    Replaces Mule http:listener + flow body.
    """
    method = event.get("httpMethod") or event.get("requestContext", {}).get("http", {}).get("method", "")
    path = event.get("path") or event.get("rawPath", "")
    logger.info("Request | method=%s path=%s", method, path)

    if method == "OPTIONS":
        return {"statusCode": 200, "headers": CORS_HEADERS, "body": ""}

    try:
        body_raw = event.get("body") or "{}"
        body = json.loads(body_raw) if isinstance(body_raw, str) else (body_raw or {})
        query_params = event.get("queryStringParameters") or {}
        path_params = event.get("pathParameters") or {}
        headers = event.get("headers") or {}

        result = route_request(method, path, body, query_params, path_params, headers)
        return {
            "statusCode": result.get("statusCode", 200),
            "headers": {**CORS_HEADERS, **result.get("headers", {})},
            "body": json.dumps(result.get("body", {})),
        }
    except ValueError as exc:
        return {"statusCode": 400, "headers": CORS_HEADERS, "body": json.dumps({"error": str(exc)})}
    except Exception as exc:
        logger.exception("Unhandled error")
        return {"statusCode": 500, "headers": CORS_HEADERS, "body": json.dumps({"error": "Internal server error"})}


def route_request(method, path, body, query_params, path_params, headers):
    """Route to the correct handler based on HTTP method and path."""
    if method == "GET" and path.startswith("/api/resource"):
        return handle_get(query_params, path_params, headers)
    if method == "POST" and path.startswith("/api/resource"):
        return handle_post(body, headers)
    raise ValueError(f"Unsupported route: {method} {path}")


def handle_get(query_params, path_params, headers):
    # Implement GET logic
    return {"statusCode": 200, "body": {}}


def handle_post(body, headers):
    # Implement POST logic
    return {"statusCode": 201, "body": {}}
```

## TypeScript — API Gateway Proxy Handler

```typescript
import { APIGatewayProxyEventV2, APIGatewayProxyResultV2 } from "aws-lambda";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": process.env.CORS_ORIGIN ?? "*",
  "Content-Type": "application/json",
};

export const handler = async (event: APIGatewayProxyEventV2): Promise<APIGatewayProxyResultV2> => {
  const method = event.requestContext.http.method;
  const path = event.rawPath;
  console.log(`Request | method=${method} path=${path}`);

  try {
    const body = event.body ? JSON.parse(event.body) : {};
    const queryParams = event.queryStringParameters ?? {};
    const pathParams = event.pathParameters ?? {};
    const result = await routeRequest(method, path, body, queryParams, pathParams);
    return {
      statusCode: result.statusCode ?? 200,
      headers: { ...CORS_HEADERS, ...result.headers },
      body: JSON.stringify(result.body),
    };
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    return { statusCode: 500, headers: CORS_HEADERS, body: JSON.stringify({ error: msg }) };
  }
};

async function routeRequest(method: string, path: string, body: unknown, queryParams: Record<string, string | undefined>, pathParams: Record<string, string | undefined>) {
  if (method === "GET") return handleGet(queryParams, pathParams);
  if (method === "POST") return handlePost(body);
  throw new Error(`Unsupported route: ${method} ${path}`);
}

async function handleGet(queryParams: Record<string, string | undefined>, pathParams: Record<string, string | undefined>) {
  return { statusCode: 200, body: {} };
}

async function handlePost(body: unknown) {
  return { statusCode: 201, body: {} };
}
```

