## Python — pg8000 (PostgreSQL, RDS Proxy compatible)

```python
import pg8000.native
import os

def get_connection():
    return pg8000.native.Connection(
        host=os.environ["DB_HOST"],
        port=int(os.environ.get("DB_PORT", "5432")),
        database=os.environ["DB_NAME"],
        user=os.environ["DB_USER"],
        password=os.environ["DB_PASSWORD"],
        ssl_context=True,
    )

# SELECT pattern
def select_records(table: str, where_clause: str, params: list):
    conn = get_connection()
    try:
        rows = conn.run(f"SELECT * FROM {table} WHERE {where_clause}", *params)
        columns = [col["name"] for col in conn.columns]
        return [dict(zip(columns, row)) for row in rows]
    finally:
        conn.close()

# INSERT pattern
def insert_record(table: str, data: dict) -> int:
    conn = get_connection()
    try:
        columns = ", ".join(data.keys())
        placeholders = ", ".join(f":{k}" for k in data.keys())
        sql = f"INSERT INTO {table} ({columns}) VALUES ({placeholders}) RETURNING id"
        result = conn.run(sql, **data)
        return result[0][0]
    finally:
        conn.close()

# UPDATE pattern
def update_records(table: str, updates: dict, where_clause: str, params: list):
    conn = get_connection()
    try:
        set_clause = ", ".join(f"{k} = :{k}" for k in updates.keys())
        sql = f"UPDATE {table} SET {set_clause} WHERE {where_clause}"
        conn.run(sql, **updates)
    finally:
        conn.close()

# DELETE pattern
def delete_records(table: str, where_clause: str, params: list):
    conn = get_connection()
    try:
        conn.run(f"DELETE FROM {table} WHERE {where_clause}", *params)
    finally:
        conn.close()
```

## TypeScript — AWS SDK RDS Data API

```typescript
import { RDSDataClient, ExecuteStatementCommand } from "@aws-sdk/client-rds-data";

const client = new RDSDataClient({ region: process.env.AWS_REGION });

async function executeSQL(sql: string, parameters: Array<{name: string; value: {stringValue?: string; longValue?: number; booleanValue?: boolean}}>) {
  const command = new ExecuteStatementCommand({
    resourceArn: process.env.DB_CLUSTER_ARN!,
    secretArn: process.env.DB_SECRET_ARN!,
    database: process.env.DB_NAME!,
    sql,
    parameters,
    includeResultMetadata: true,
  });
  return client.send(command);
}

// SELECT
async function selectRecords(table: string, whereColumn: string, whereValue: string) {
  const result = await executeSQL(
    `SELECT * FROM ${table} WHERE ${whereColumn} = :value`,
    [{ name: "value", value: { stringValue: whereValue } }]
  );
  const cols = result.columnMetadata?.map(c => c.name!) ?? [];
  return result.records?.map(row =>
    Object.fromEntries(cols.map((col, i) => [col, Object.values(row[i])[0]]))
  ) ?? [];
}

// INSERT
async function insertRecord(table: string, data: Record<string, string>) {
  const cols = Object.keys(data).join(", ");
  const placeholders = Object.keys(data).map(k => `:${k}`).join(", ");
  const params = Object.entries(data).map(([name, value]) => ({ name, value: { stringValue: value } }));
  await executeSQL(`INSERT INTO ${table} (${cols}) VALUES (${placeholders})`, params);
}
```

