## Python — S3 Operations (replaces Mule file:read / file:write / S3 connector)

```python
import boto3
import json
import os
import logging

logger = logging.getLogger()
s3 = boto3.client("s3", region_name=os.environ.get("AWS_REGION", "us-east-1"))


def read_object(bucket: str, key: str) -> bytes:
    """Replaces Mule file:read or s3:read. Returns raw bytes."""
    response = s3.get_object(Bucket=bucket, Key=key)
    data = response["Body"].read()
    logger.info("Read s3://%s/%s (%d bytes)", bucket, key, len(data))
    return data


def read_json(bucket: str, key: str) -> dict:
    """Read S3 object and parse as JSON."""
    return json.loads(read_object(bucket, key))


def write_object(bucket: str, key: str, data: bytes, content_type: str = "application/octet-stream") -> None:
    """Replaces Mule file:write or s3:write."""
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    logger.info("Wrote s3://%s/%s (%d bytes)", bucket, key, len(data))


def write_json(bucket: str, key: str, payload: dict) -> None:
    """Write Python dict as JSON to S3."""
    write_object(bucket, key, json.dumps(payload).encode("utf-8"), "application/json")


def list_objects(bucket: str, prefix: str = "") -> list[dict]:
    """List objects under a prefix."""
    paginator = s3.get_paginator("list_objects_v2")
    results = []
    for page in paginator.paginate(Bucket=bucket, Prefix=prefix):
        for obj in page.get("Contents", []):
            results.append({"key": obj["Key"], "size": obj["Size"], "last_modified": str(obj["LastModified"])})
    return results


def delete_object(bucket: str, key: str) -> None:
    s3.delete_object(Bucket=bucket, Key=key)
    logger.info("Deleted s3://%s/%s", bucket, key)


def generate_presigned_url(bucket: str, key: str, expiry_seconds: int = 3600) -> str:
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expiry_seconds,
    )
```

## TypeScript — S3 Operations

```typescript
import { S3Client, GetObjectCommand, PutObjectCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";
import { Readable } from "stream";

const s3 = new S3Client({ region: process.env.AWS_REGION });

async function readObject(bucket: string, key: string): Promise<Buffer> {
  const response = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
  const stream = response.Body as Readable;
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    stream.on("data", chunk => chunks.push(Buffer.from(chunk)));
    stream.on("end", () => resolve(Buffer.concat(chunks)));
    stream.on("error", reject);
  });
}

async function readJson(bucket: string, key: string): Promise<unknown> {
  const buf = await readObject(bucket, key);
  return JSON.parse(buf.toString("utf-8"));
}

async function writeObject(bucket: string, key: string, data: Buffer, contentType = "application/octet-stream"): Promise<void> {
  await s3.send(new PutObjectCommand({ Bucket: bucket, Key: key, Body: data, ContentType: contentType }));
}

async function writeJson(bucket: string, key: string, payload: unknown): Promise<void> {
  const data = Buffer.from(JSON.stringify(payload), "utf-8");
  await writeObject(bucket, key, data, "application/json");
}
