## Python — JMS Publish Replacement

```python
import boto3
import json
import os
import logging

logger = logging.getLogger()
sqs = boto3.client("sqs", region_name=os.environ.get("AWS_REGION", "us-east-1"))


def jms_publish(payload: dict | str, queue_url: str | None = None, attributes: dict | None = None) -> str:
    """
    Replaces Mule jms:publish.
    payload: dict (serialized to JSON) or str (sent as-is)
    Returns SQS MessageId
    """
    q = queue_url or os.environ["SQS_QUEUE_URL"]
    body = json.dumps(payload) if isinstance(payload, dict) else str(payload)

    kwargs = {"QueueUrl": q, "MessageBody": body}
    if attributes:
        kwargs["MessageAttributes"] = {
            k: {"DataType": "String", "StringValue": str(v)}
            for k, v in attributes.items()
        }

    response = sqs.send_message(**kwargs)
    logger.info("Published to SQS | MessageId=%s queue=%s", response["MessageId"], q)
    return response["MessageId"]


def jms_consume(queue_url: str | None = None, max_messages: int = 10, wait_time: int = 20) -> list[dict]:
    """
    Replaces Mule jms:consume (polling).
    Returns list of parsed message bodies and deletes them from the queue.
    """
    q = queue_url or os.environ["SQS_QUEUE_URL"]
    response = sqs.receive_message(
        QueueUrl=q,
        MaxNumberOfMessages=min(max_messages, 10),
        WaitTimeSeconds=wait_time,
        AttributeNames=["All"],
        MessageAttributeNames=["All"],
    )
    messages = response.get("Messages", [])
    results = []
    for msg in messages:
        try:
            body = json.loads(msg["Body"])
        except json.JSONDecodeError:
            body = msg["Body"]
        results.append({"body": body, "messageId": msg["MessageId"], "attributes": msg.get("MessageAttributes", {})})
        # Delete after successful processing (replaces JMS acknowledgement)
        sqs.delete_message(QueueUrl=q, ReceiptHandle=msg["ReceiptHandle"])
    logger.info("Consumed %d messages from SQS", len(results))
    return results
```

## TypeScript — JMS Publish Replacement

```typescript
import { SQSClient, SendMessageCommand, ReceiveMessageCommand, DeleteMessageCommand } from "@aws-sdk/client-sqs";

const sqsClient = new SQSClient({ region: process.env.AWS_REGION });

async function jmsPublish(payload: unknown, queueUrl?: string): Promise<string> {
  const url = queueUrl ?? process.env.SQS_QUEUE_URL!;
  const body = typeof payload === "string" ? payload : JSON.stringify(payload);
  const response = await sqsClient.send(new SendMessageCommand({ QueueUrl: url, MessageBody: body }));
  console.log(`Published to SQS | MessageId=${response.MessageId}`);
  return response.MessageId!;
}

async function jmsConsume(queueUrl?: string, maxMessages = 10): Promise<unknown[]> {
  const url = queueUrl ?? process.env.SQS_QUEUE_URL!;
  const response = await sqsClient.send(new ReceiveMessageCommand({
    QueueUrl: url,
    MaxNumberOfMessages: maxMessages,
    WaitTimeSeconds: 20,
  }));
  const messages = response.Messages ?? [];
  const results: unknown[] = [];
  for (const msg of messages) {
    const body = msg.Body ? JSON.parse(msg.Body) : {};
    results.push(body);
    await sqsClient.send(new DeleteMessageCommand({ QueueUrl: url, ReceiptHandle: msg.ReceiptHandle! }));
  }
  return results;
}
```

