```python
import os
import logging
from simple_salesforce import Salesforce, SFType

logger = logging.getLogger()


def get_sf_client() -> Salesforce:
    """
    Build Salesforce client from environment variables.
    Replaces Mule salesforce:config with OAuth credentials.
    """
    return Salesforce(
        username=os.environ["SF_USERNAME"],
        password=os.environ["SF_PASSWORD"],
        security_token=os.environ["SF_SECURITY_TOKEN"],
        domain=os.environ.get("SF_DOMAIN", "login"),  # "test" for sandbox
    )


# QUERY (replaces salesforce:query)
def salesforce_query(soql: str) -> list[dict]:
    """
    Execute a SOQL query and return all records.
    Handles pagination automatically.
    """
    sf = get_sf_client()
    logger.info("SF SOQL: %s", soql)
    result = sf.query_all(soql)
    records = result.get("records", [])
    logger.info("SF query returned %d records", len(records))
    # Remove Salesforce metadata attributes
    return [{k: v for k, v in r.items() if k != "attributes"} for r in records]


# RETRIEVE by ID (replaces salesforce:retrieve)
def salesforce_get(object_type: str, record_id: str, fields: list[str] | None = None) -> dict:
    sf = get_sf_client()
    obj = sf.__getattr__(object_type)
    if fields:
        record = obj.get(record_id, fields=",".join(fields))
    else:
        record = obj.get(record_id)
    return {k: v for k, v in record.items() if k != "attributes"}


# CREATE (replaces salesforce:create)
def salesforce_create(object_type: str, data: dict) -> str:
    sf = get_sf_client()
    result = sf.__getattr__(object_type).create(data)
    if not result.get("success"):
        raise RuntimeError(f"Salesforce create failed: {result.get('errors')}")
    record_id = result["id"]
    logger.info("SF created %s Id=%s", object_type, record_id)
    return record_id


# UPDATE (replaces salesforce:update)
def salesforce_update(object_type: str, record_id: str, data: dict) -> None:
    sf = get_sf_client()
    result = sf.__getattr__(object_type).update(record_id, data)
    logger.info("SF updated %s Id=%s result=%s", object_type, record_id, result)


# UPSERT (replaces salesforce:upsert)
def salesforce_upsert(object_type: str, external_id_field: str, data: dict) -> dict:
    sf = get_sf_client()
    external_id = data[external_id_field]
    result = sf.__getattr__(object_type).upsert(f"{external_id_field}/{external_id}", data)
    logger.info("SF upserted %s %s=%s", object_type, external_id_field, external_id)
    return result


# DELETE (replaces salesforce:delete)
def salesforce_delete(object_type: str, record_id: str) -> None:
    sf = get_sf_client()
    sf.__getattr__(object_type).delete(record_id)
    logger.info("SF deleted %s Id=%s", object_type, record_id)
```

