## Mule Error Handler Semantics

`on-error-continue`: Catches the error, executes the handler body, then CONTINUES the flow (returns 200).
`on-error-propagate`: Catches the error, executes the handler body, then RE-RAISES the error (flow fails).

## Python Migration

```python
import logging
import json

logger = logging.getLogger()


def handler(event, context):
    try:
        result = run_flow(event)
        return {"statusCode": 200, "body": json.dumps(result)}
    except BusinessError as exc:
        # on-error-continue: log, set error payload, CONTINUE
        logger.warning("Business error handled | %s", exc)
        return {
            "statusCode": 200,   # continues — same as on-error-continue
            "body": json.dumps({"error": str(exc), "handled": True}),
        }
    except SystemError as exc:
        # on-error-propagate: log then re-raise (Lambda will retry / DLQ)
        logger.error("System error propagated | %s", exc)
        return {"statusCode": 500, "body": json.dumps({"error": str(exc)})}


class BusinessError(Exception):
    """Maps to Mule on-error-continue error types (APP:*, VALIDATION:*)."""

class SystemError(Exception):
    """Maps to Mule on-error-propagate error types (CONNECTIVITY:*, TIMEOUT:*)."""


def run_flow(event: dict) -> dict:
    # Main flow logic here
    return {}
```

## TypeScript Migration

```typescript
export const handler = async (event: unknown) => {
  try {
    const result = await runFlow(event);
    return { statusCode: 200, body: JSON.stringify(result) };
  } catch (err: unknown) {
    if (err instanceof BusinessError) {
      // on-error-continue
      console.warn("Business error handled:", err.message);
      return { statusCode: 200, body: JSON.stringify({ error: err.message, handled: true }) };
    }
    // on-error-propagate
    console.error("System error propagated:", err);
    return { statusCode: 500, body: JSON.stringify({ error: String(err) }) };
  }
};

class BusinessError extends Error {}
class SystemError extends Error {}

async function runFlow(event: unknown): Promise<unknown> {
  // Main flow logic
  return {};
}
```

